/**
 * Shared by the `@pattern-stack/jobs` Postgres suites: the DDL for the package's tables, generated by drizzle-kit from
 * `@pattern-stack/jobs/postgres`'s own Drizzle definitions (never a hand-written copy that could drift), and the
 * tenants and user the contract writes under. Tenants are text, not uuids: the fixed system tenant is one of them.
 */
import * as tables from '@pattern-stack/jobs/postgres';
import { SYSTEM_TENANT } from '@pattern-stack/jobs';

export const TENANTS = [SYSTEM_TENANT, 'tenant-b'] as const;
export const USER = 'user-1';

/** The CREATE statements for every job table, in dependency order. */
export async function jobsDdl(): Promise<string[]> {
  const { generateDrizzleJson, generateMigration } = await import('drizzle-kit/api-postgres');
  const schema = {
    jobRuns: tables.jobRuns,
    jobRunSteps: tables.jobRunSteps,
    jobRunItems: tables.jobRunItems,
    jobRunChunks: tables.jobRunChunks,
    jobRunValues: tables.jobRunValues,
    jobItemResults: tables.jobItemResults,
    jobRunEvents: tables.jobRunEvents,
  };
  const empty = await generateDrizzleJson({});
  const full = await generateDrizzleJson(schema);
  return generateMigration(empty, full);
}
